/* ---------- dissection (signature 3D scroll mechanic) ---------- */
.dt-dissection {
  --explode: 1;
  position: relative;
  border-top: 1.5px solid var(--color-ink);
  background: var(--color-ceramic);
  padding: 4.5rem var(--dt-gutter) 5.5rem;
  z-index: 2;
}

.dt-dissection-grid {
  width: min(100%, var(--dt-max));
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(1.5rem, 4vw, 4rem);
  align-items: start;
}

.dt-dissection-stage {
  position: sticky;
  top: 76px;
  display: grid;
  gap: 0.9rem;
}

.dt-stage-card {
  position: relative;
  border-radius: var(--dt-radius);
  border: 1.5px solid var(--color-ink);
  background: var(--color-paper);
  padding: 1rem;
  display: grid;
  gap: 0.75rem;
}

.dt-stage-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.dt-stage-badge {
  padding: 0.2rem 0.55rem;
  border-radius: 3px;
  background: var(--color-ceramic);
  border: 1px solid var(--color-rule);
  color: var(--color-slate);
}

.dt-stage-badge[data-live="true"] {
  background: var(--color-ink);
  color: var(--color-phosphor);
  border-color: var(--color-ink);
}

.dt-canvas {
  position: relative;
  width: 100%;
  aspect-ratio: 480 / 410;
  max-height: 58svh;
  border-radius: 4px;
  border: 1px solid var(--color-rule);
  background-color: var(--color-ceramic);
  background-image: linear-gradient(
      to right,
      color-mix(in srgb, var(--color-rule) 42%, transparent) 1px,
      transparent 1px
    ),
    linear-gradient(
      to bottom,
      color-mix(in srgb, var(--color-rule) 42%, transparent) 1px,
      transparent 1px
    );
  background-size: 28px 28px;
  overflow: clip;
}

.dt-canvas-poster {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background: var(--color-ceramic);
  transition: opacity var(--dur-slow) var(--ease-out);
}

.dt-canvas-gl {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  touch-action: none;
  transition: opacity var(--dur-slow) var(--ease-out);
}

.dt-canvas-gl[data-live="true"] {
  opacity: 1;
}

.dt-stage-card[data-phase="live"] .dt-canvas-poster {
  opacity: 0;
  pointer-events: none;
}

.dt-canvas-start {
  position: absolute;
  left: 50%;
  bottom: 12px;
  transform: translateX(-50%);
  z-index: 3;
  width: max-content;
  white-space: nowrap;
}

.dt-canvas-note {
  position: absolute;
  inset: auto 0 8px 0;
  text-align: center;
  margin: 0;
  color: var(--color-amber);
}

.dt-stage-hud {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.dt-hud-btn {
  padding: 0.45em 0.85em;
  border-radius: 4px;
  border: 1px solid var(--color-ink);
  background: var(--color-ceramic);
  color: var(--color-ink);
  font-family: var(--font-mono);
  font-size: 0.74rem;
  cursor: pointer;
  transition: transform var(--dur-instant) var(--ease-spring), background-color var(--dur-fast),
    color var(--dur-fast);
}

.dt-hud-btn:active {
  transform: scale(0.96);
}

.dt-hud-btn[aria-pressed="true"] {
  background: var(--color-ink);
  color: var(--color-phosphor);
}

@media (hover: hover) and (pointer: fine) {
  .dt-hud-btn:hover {
    border-color: var(--color-emerald);
  }
}

.dt-step-rail {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.dt-rail-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.42em 0.78em;
  border-radius: 4px;
  border: 1px solid var(--color-rule);
  background: var(--color-paper);
  color: var(--color-ink);
  font-size: 0.82rem;
  cursor: pointer;
  transition: transform var(--dur-instant) var(--ease-spring), background-color var(--dur-fast),
    color var(--dur-fast), border-color var(--dur-fast);
}

.dt-rail-btn[aria-current="step"] {
  background: var(--color-emerald);
  color: var(--color-ceramic);
  border-color: var(--color-emerald);
}

.dt-rail-btn:active {
  transform: scale(0.96);
}

.dt-dissection-panel {
  display: grid;
  gap: 2rem;
}

.dt-dissection-intro {
  display: grid;
  gap: 0.6rem;
}

.dt-pass-cards {
  display: grid;
  gap: 1.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.dt-pass-card {
  display: grid;
  gap: 0.75rem;
  padding: 1.5rem;
  border-radius: var(--dt-radius);
  border: 1.5px solid var(--color-rule);
  background: var(--color-paper);
  transition: border-color var(--dur-base) var(--ease-out), background-color var(--dur-base) var(--ease-out),
    transform var(--dur-base) var(--ease-out), opacity var(--dur-base) var(--ease-out);
}

.dt-pass-card[data-selected="true"] {
  border-color: var(--color-emerald);
  background: var(--color-ceramic);
}

.dt-pass-card[data-enabled="false"] {
  opacity: 0.56;
}

.dt-pass-card-top {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.5rem;
  padding-bottom: 0.6rem;
  border-bottom: 1px solid var(--color-rule);
}

.dt-pass-code {
  color: var(--color-slate);
}

.dt-pass-ms {
  color: var(--color-emerald);
  font-weight: 700;
}

.dt-pass-role {
  margin: 0;
  font-weight: 600;
  color: var(--color-ink);
}

.dt-pass-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.9rem;
  padding-top: 0.5rem;
}

.dt-pass-meta .dt-btn {
  margin-left: auto;
}

@media (hover: hover) and (pointer: fine) {
  .dt-pass-card:hover {
    border-color: var(--color-ink);
    transform: translateY(-2px);
  }
}

@media (max-width: 860px) {
  .dt-dissection-grid {
    grid-template-columns: 1fr;
  }
  .dt-dissection-stage {
    position: static;
  }
  .dt-pass-meta .dt-btn {
    margin-left: 0;
  }
}

/* ---------- budget lab ---------- */
.dt-budget {
  position: relative;
  background: var(--color-paper);
  border-top: 1.5px solid var(--color-rule);
  padding: 5.5rem var(--dt-gutter) 7rem;
  z-index: 3;
}

.dt-budget-bench {
  width: min(100%, var(--dt-max));
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  gap: 1.75rem;
  padding: 1.5rem;
  border-radius: var(--dt-radius);
  border: 1.5px solid var(--color-ink);
  background: var(--color-ceramic);
}

.dt-budget-controls,
.dt-budget-readout {
  display: grid;
  gap: 1.25rem;
  align-content: start;
}

.dt-control-block {
  display: grid;
  gap: 0.75rem;
  padding: 1.1rem;
  border-radius: 4px;
  border: 1px solid var(--color-rule);
  background: var(--color-paper);
}

.dt-control-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
  color: var(--color-slate);
}

.dt-toggle-list {
  display: grid;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.dt-toggle-row {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.62rem 0.78rem;
  border-radius: 4px;
  border: 1px solid var(--color-rule);
  background: var(--color-ceramic);
  color: var(--color-ink);
  font: inherit;
  cursor: pointer;
  transition: border-color var(--dur-fast), transform var(--dur-instant) var(--ease-spring);
}

.dt-toggle-row:active {
  transform: scale(0.99);
}

.dt-toggle-left {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
}

.dt-toggle-code {
  color: var(--color-emerald);
}

.dt-toggle-name {
  font-weight: 500;
}

.dt-toggle-right {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
}

.dt-switch-track {
  position: relative;
  width: 34px;
  height: 18px;
  border-radius: 999px;
  background: var(--color-rule);
  transition: background-color var(--dur-fast);
}

.dt-switch-thumb {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--color-ceramic);
  transition: transform var(--dur-base) var(--ease-spring);
}

.dt-toggle-row[data-enabled="true"] .dt-switch-track {
  background: var(--color-emerald);
}

.dt-toggle-row[data-enabled="true"] .dt-switch-thumb {
  transform: translateX(16px);
}

.dt-slider {
  width: 100%;
  accent-color: var(--color-emerald);
  cursor: pointer;
}

.dt-fps-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.dt-meter-card {
  display: grid;
  gap: 1rem;
  padding: 1.25rem;
  border-radius: 4px;
  border: 1.5px solid var(--color-ink);
  background: var(--color-paper);
}

.dt-meter-top {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.75rem;
}

.dt-meter-label {
  color: var(--color-slate);
}

.dt-meter-value {
  font-size: clamp(2rem, 3.6vw, 2.8rem);
  margin-top: 0.25rem;
}

.dt-status-pill {
  padding: 0.3em 0.65em;
  border-radius: 4px;
  background: var(--color-ceramic);
  border: 1px solid var(--color-emerald);
  color: var(--color-emerald);
}

.dt-status-pill[data-over="true"] {
  border-color: var(--color-amber);
  color: var(--color-amber);
}

.dt-meter-track {
  height: 12px;
  border-radius: 3px;
  border: 1px solid var(--color-rule);
  background: var(--color-ceramic);
  overflow: clip;
}

.dt-meter-fill {
  height: 100%;
  width: 100%;
  background: var(--color-emerald);
  transform-origin: left;
  transition: transform var(--dur-base) var(--ease-out-expo), background-color var(--dur-fast);
}

.dt-meter-card[data-over="true"] .dt-meter-fill {
  background: var(--color-amber);
}

.dt-meter-kpis {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.75rem;
  margin: 0;
  padding-top: 0.75rem;
  border-top: 1px solid var(--color-rule);
}

.dt-meter-kpis dt {
  font-size: 0.8rem;
  color: var(--color-slate);
}

.dt-meter-kpis dd {
  margin: 0.2rem 0 0;
  font-weight: 700;
}

.dt-kernel-card {
  display: grid;
  gap: 0.75rem;
  padding: 1.25rem;
  border-radius: 4px;
  background: var(--color-ink);
  color: var(--color-paper);
}

.dt-kernel-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}

.dt-kernel-tab {
  padding: 0.28em 0.68em;
  border-radius: 3px;
  border: 1px solid color-mix(in srgb, var(--color-paper) 25%, transparent);
  background: transparent;
  color: var(--color-paper);
  font-family: var(--font-mono);
  font-size: 0.76rem;
  cursor: pointer;
}

.dt-kernel-tab[data-active="true"] {
  background: var(--color-phosphor);
  color: var(--color-ink);
  border-color: var(--color-phosphor);
  font-weight: 700;
}

.dt-kernel-meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.5rem;
  color: var(--color-phosphor);
}

.dt-kernel-code {
  margin: 0;
  padding: 0.9rem;
  border-radius: 4px;
  border: 1px solid color-mix(in srgb, var(--color-paper) 16%, transparent);
  background: color-mix(in srgb, var(--color-paper) 4%, var(--color-ink));
  color: var(--color-paper);
  font-family: var(--font-mono);
  font-size: 0.76rem;
  line-height: 1.65;
  overflow-x: auto;
}

@media (max-width: 860px) {
  .dt-budget-bench {
    grid-template-columns: 1fr;
    padding: 1rem;
  }
  .dt-meter-kpis {
    grid-template-columns: 1fr;
  }
}

/* ---------- architecture (dark graphite ink slab) ---------- */
.dt-arch {
  position: relative;
  margin-top: -24px;
  border-radius: var(--dt-slab-radius) var(--dt-slab-radius) 0 0;
  background: var(--color-ink);
  color: var(--color-paper);
  padding: 0 var(--dt-gutter) 7rem;
  z-index: 4;
  overflow: clip;
}

.dt-marquee {
  margin-inline: calc(var(--dt-gutter) * -1);
  padding-block: 1.75rem 2.25rem;
  border-bottom: 1px solid color-mix(in srgb, var(--color-paper) 14%, transparent);
  overflow: clip;
}

.dt-marquee-lane {
  display: flex;
  width: max-content;
}

.dt-marquee-track {
  display: flex;
  flex: none;
  margin: 0;
  padding: 0;
  list-style: none;
}

.dt-marquee-track li {
  display: flex;
  align-items: center;
  gap: 1.75rem;
  padding-right: 1.75rem;
  font-family: var(--font-display);
  font-size: clamp(1.8rem, 4.5vw, 3.6rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.dt-marquee-dot {
  display: block;
  width: 10px;
  height: 10px;
  border-radius: 2px;
  background: var(--color-phosphor);
}

.dt-arch-inner {
  width: min(100%, var(--dt-max));
  margin: 3.5rem auto 0;
  display: grid;
  gap: 3.5rem;
}

.dt-workflow {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.dt-workflow-step {
  position: relative;
  padding-top: 1.25rem;
  display: grid;
  gap: 0.55rem;
  align-content: start;
}

.dt-workflow-rule {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 2px;
  background: var(--color-phosphor);
  transform-origin: left;
}

.dt-workflow-code {
  color: var(--color-phosphor);
}

.dt-workflow-step p {
  margin: 0;
  color: color-mix(in srgb, var(--color-paper) 74%, transparent);
}

.dt-pillars {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.4rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.dt-pillar-cell {
  display: grid;
}

.dt-pillar-card {
  --rx: 0deg;
  --ry: 0deg;
  position: relative;
  display: grid;
  gap: 0.75rem;
  align-content: start;
  padding: 1.75rem;
  border-radius: var(--dt-radius);
  border: 1px solid color-mix(in srgb, var(--color-paper) 18%, transparent);
  background: color-mix(in srgb, var(--color-paper) 4%, var(--color-ink));
  overflow: clip;
  transform: perspective(900px) rotateX(var(--rx)) rotateY(var(--ry));
  transition: transform var(--dur-base) var(--ease-out), opacity var(--dur-base) var(--ease-out),
    border-color var(--dur-fast);
}

.dt-pillar-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(
    320px circle at var(--mx, 50%) var(--my, 50%),
    color-mix(in srgb, var(--color-phosphor) 15%, transparent),
    transparent 62%
  );
  transition: opacity var(--dur-base);
}

.dt-pillar-top {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
}

.dt-pillar-code {
  color: color-mix(in srgb, var(--color-paper) 64%, transparent);
}

.dt-pillar-metric {
  color: var(--color-phosphor);
}

.dt-pillar-card p {
  margin: 0;
  color: color-mix(in srgb, var(--color-paper) 78%, transparent);
}

@media (hover: hover) and (pointer: fine) {
  .dt-pillar-card:hover {
    transform: perspective(900px) translateY(-6px) rotateX(var(--rx)) rotateY(var(--ry));
    border-color: var(--color-phosphor);
  }
  .dt-pillar-card:hover::before {
    opacity: 1;
  }
  .dt-pillars:has(.dt-pillar-card:hover) .dt-pillar-card:not(:hover) {
    opacity: 0.65;
  }
}

.dt-arch-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.5rem;
  margin: 0;
  padding-top: 2rem;
  border-top: 1px solid color-mix(in srgb, var(--color-paper) 16%, transparent);
}

.dt-arch-metrics dt {
  font-family: var(--font-mono);
  font-size: 0.76rem;
  color: color-mix(in srgb, var(--color-paper) 70%, transparent);
}

.dt-arch-metrics dd {
  margin: 0.3rem 0 0;
  font-size: clamp(1.8rem, 3.2vw, 2.6rem);
  color: var(--color-phosphor);
}

@media (max-width: 960px) {
  .dt-workflow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .dt-pillars {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 560px) {
  .dt-workflow,
  .dt-arch-metrics {
    grid-template-columns: 1fr;
  }
}

/* ---------- access & brief form ---------- */
.dt-access {
  position: relative;
  margin-top: -24px;
  border-radius: var(--dt-slab-radius) var(--dt-slab-radius) 0 0;
  background: var(--color-paper);
  padding: 5.5rem var(--dt-gutter) 6.5rem;
  z-index: 5;
