  top: 88px;
}

.dt-summary-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
}

.dt-summary-eyebrow {
  color: var(--color-emerald);
}

.dt-summary-ref {
  padding: 0.18em 0.5em;
  border-radius: 3px;
  background: var(--color-paper);
  border: 1px solid var(--color-rule);
