  display: grid;
}

.dt-access-form-wrap > * {
  grid-area: 1 / 1;
}

.dt-access-form-wrap form {
  display: grid;
  gap: 1.15rem;
  padding: 2rem;
  border-radius: var(--dt-radius);
  border: 1.5px solid var(--color-ink);
  background: var(--color-ceramic);
  transition: opacity var(--dur-base) var(--ease-out), transform var(--dur-slow) var(--ease-out-expo);
