.dt-runtime-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.dt-field {
  position: relative;
}

.dt-field input,
.dt-field textarea {
  width: 100%;
  padding: 1.45rem 0.25rem 0.5rem;
  border: 0;
  border-bottom: 1.5px solid var(--color-rule);
  background: transparent;
  font: inherit;
  color: var(--color-ink);
  border-radius: 0;
  resize: vertical;
  outline: none;
}

.dt-field label {
  position: absolute;
  left: 0.25rem;
  top: 1.1rem;
  color: var(--color-slate);
  pointer-events: none;
  transform-origin: left top;
  transition: transform var(--dur-base) var(--ease-out-expo), color var(--dur-fast);
}

.dt-field input:focus ~ label,
.dt-field input:not(:placeholder-shown) ~ label,
.dt-field textarea:focus ~ label,
.dt-field textarea:not(:placeholder-shown) ~ label {
  transform: translateY(-0.92rem) scale(0.78);
  color: var(--color-emerald);
}

.dt-field::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  background: var(--color-emerald);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--dur-base) var(--ease-out-expo);
  pointer-events: none;
}

.dt-field:focus-within::after {
  transform: scaleX(1);
}

.dt-field-error {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--dur-base) var(--ease-out-expo);
}

.dt-field-error[data-open="true"] {
  grid-template-rows: 1fr;
}

.dt-field-error p {
  overflow: hidden;
  margin: 0;
  color: var(--color-amber);
  font-size: 0.85rem;
  min-height: 0;
}

.dt-field-error[data-open="true"] p {
  padding-top: 0.35rem;
}

.dt-field[data-invalid="true"] input,
.dt-field[data-invalid="true"] textarea {
  border-bottom-color: var(--color-amber);
}

.dt-submit {
  justify-self: start;
}

.dt-spinner {
  display: none;
  width: 0.95em;
  height: 0.95em;
  border-radius: 50%;
  border: 2px solid color-mix(in srgb, var(--color-ceramic) 35%, transparent);
  border-top-color: var(--color-ceramic);
}

.dt-submit[data-loading="true"] .dt-spinner {
  display: block;
}

.dt-success {
  display: grid;
  align-content: center;
  justify-items: start;
  gap: 1rem;
  padding: 2.25rem;
  border-radius: var(--dt-radius);
  background: var(--color-ink);
  color: var(--color-paper);
  opacity: 0;
  pointer-events: none;
  transform: translateY(20px) scale(0.98);
  transition: opacity var(--dur-slow) var(--ease-out), transform var(--dur-slow) var(--ease-out-expo);
}

.dt-success p {
  margin: 0;
  color: color-mix(in srgb, var(--color-paper) 82%, transparent);
  max-width: 48ch;
}

.dt-success-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 0.35rem;
}

.dt-ref {
  color: var(--color-phosphor);
}

.dt-stamp {
  width: 84px;
  height: 84px;
  fill: none;
  stroke: var(--color-phosphor);
  stroke-width: 4;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.dt-stamp-ring,
.dt-stamp-check {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}

.dt-access-form-wrap[data-state="success"] form {
  opacity: 0;
  transform: translateY(-14px) scale(0.98);
  pointer-events: none;
}

.dt-access-form-wrap[data-state="success"] .dt-success {
  opacity: 1;
  pointer-events: auto;
  transform: none;
}

.dt-access-form-wrap[data-state="success"] .dt-stamp-ring {
  stroke-dashoffset: 0;
  transition: stroke-dashoffset var(--dur-slow) var(--ease-in-out) 160ms;
}

.dt-access-form-wrap[data-state="success"] .dt-stamp-check {
  stroke-dashoffset: 0;
  transition: stroke-dashoffset var(--dur-base) var(--ease-out) 680ms;
}

@media (max-width: 860px) {
  .dt-access-grid {
    grid-template-columns: 1fr;
  }
  .dt-access-summary {
    position: static;
  }
  .dt-access-form-wrap form {
    padding: 1.35rem;
  }
}

/* ---------- footer ---------- */
.dt-footer {
  position: relative;
  margin-top: -24px;
  border-radius: var(--dt-slab-radius) var(--dt-slab-radius) 0 0;
  background: var(--color-ink);
  color: var(--color-paper);
  padding: 4.5rem var(--dt-gutter) 3rem;
  z-index: 6;
}

.dt-footer-inner {
  width: min(100%, var(--dt-max));
  margin: 0 auto;
  display: grid;
  gap: 2.25rem;
}

.dt-footer-top {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid color-mix(in srgb, var(--color-paper) 16%, transparent);
}

.dt-footer-tag {
  margin: 0;
  color: var(--color-phosphor);
}

.dt-footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.dt-footer-brand .dt-logo-mark {
  width: clamp(44px, 7vw, 84px);
  height: auto;
}

.dt-footer-brand .dt-logo-word {
  font-size: clamp(2.8rem, 11vw, 7.2rem);
}

.dt-footer-bottom {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.dt-footer .dt-fineprint {
  color: color-mix(in srgb, var(--color-paper) 68%, transparent);
}

/* ---------- motion: applied strictly under prefers-reduced-motion: no-preference ---------- */
@media (prefers-reduced-motion: no-preference) {
  [data-reveal] {
    transition: opacity var(--dur-slow) var(--ease-out), transform var(--dur-slow) var(--ease-out),
      clip-path var(--dur-slow) var(--ease-in-out);
    transition-delay: calc(var(--delay, 0ms) + var(--i, 0) * var(--stagger));
  }

  [data-reveal="rise"]:not([data-in="true"]) {
    opacity: 0;
    transform: translateY(var(--reveal-shift));
  }

  [data-reveal="scale"]:not([data-in="true"]) {
    opacity: 0;
    transform: translateY(28px) scale(0.95);
  }

  [data-reveal="wipe"]:not([data-in="true"]) {
    clip-path: inset(0 0 100% 0 round 6px);
  }

  [data-reveal="draw"]:not([data-in="true"]) {
    transform: scaleX(0);
    transform-origin: left;
  }

  [data-reveal="mask"] .dt-word-inner {
    transition: transform var(--dur-slow) var(--ease-out-expo);
    transition-delay: calc(var(--delay, 0ms) + var(--wi, 0) * 40ms);
  }

  [data-reveal="mask"]:not([data-in="true"]) .dt-word-inner {
    transform: translateY(115%);
  }

  .dt-workflow-step .dt-workflow-rule {
    transition: transform var(--dur-slow) var(--ease-in-out);
    transition-delay: calc(var(--delay, 0ms) + var(--i, 0) * var(--stagger));
  }

  .dt-workflow-step:not([data-in="true"]) .dt-workflow-rule {
    transform: scaleX(0);
  }

  /* Hero choreographed load sequence before hydration */
  [data-load] {
    animation: dt-load 320ms var(--ease-out-expo) both;
  }
  [data-load="visual"] {
    animation-name: dt-plate-in;
    animation-delay: 20ms;
  }
  [data-load="eyebrow"] {
    animation-delay: 30ms;
  }
  [data-load="lede"] {
    animation-name: dt-glide-in;
    animation-delay: 40ms;
  }
  [data-load="actions"] {
    animation-delay: 100ms;
  }
  [data-load="stats"] {
    animation-delay: 130ms;
  }
  [data-load="cue"] {
    animation-delay: 180ms;
  }
  [data-load="title"] {
    animation: none;
  }
  [data-load="title"] .dt-word-inner {
    animation: dt-mask-rise 340ms var(--ease-out-expo) both;
    animation-delay: calc(40ms + var(--wi, 0) * 30ms);
  }

  .dt-header-bar {
    animation: dt-drop 320ms var(--ease-out-expo) 20ms both;
  }

  .dt-nav-list li:not(.dt-nav-pill) {
    animation: dt-drop var(--dur-fast) var(--ease-out-expo) both;
    animation-delay: calc(60ms + var(--i, 0) * 30ms);
  }

  @keyframes dt-load {
    from {
      opacity: 0.01;
      transform: translateY(16px);
    }
    to {
      opacity: 1;
      transform: none;
    }
  }

  @keyframes dt-settle {
    from {
      opacity: 0.01;
      transform: scale(1.03);
    }
    to {
      opacity: 1;
      transform: none;
    }
  }

  @keyframes dt-mask-rise {
    from {
      transform: translateY(115%);
    }
    to {
      transform: none;
    }
  }

  @keyframes dt-drop {
    from {
      opacity: 0;
      transform: translateY(-16px);
    }
    to {
      opacity: 1;
      transform: none;
    }
  }

  /* Restrained ambient motion (<= 3 loops in view, paused offscreen) */
  .dt-readout-dot {
    animation: dt-pulse 2.2s ease-in-out infinite;
  }
  .dt-scroll-cue i {
    animation: dt-cue 2.2s var(--ease-in-out) infinite;
  }
  .dt-marquee-lane {
    animation: dt-marquee 42s linear infinite;
  }
  .dt-marquee[data-offscreen="true"] .dt-marquee-lane,
  .dt-marquee:hover .dt-marquee-lane,
  .dt-marquee:focus-within .dt-marquee-lane,
  .dt-marquee:focus .dt-marquee-lane {
    animation-play-state: paused;
  }
  [data-hero-away="true"] .dt-hero * {
    animation-play-state: paused;
  }
  .dt-spinner {
    animation: dt-spin 650ms linear infinite;
  }
  .dt-field[data-invalid="true"] {
    animation: dt-shake 280ms var(--ease-out);
  }

  @keyframes dt-pulse {
    0%,
    100% {
      opacity: 1;
    }
    50% {
      opacity: 0.35;
    }
  }
  @keyframes dt-cue {
    0% {
      transform: scaleY(0);
      transform-origin: top;
    }
    50% {
      transform: scaleY(1);
      transform-origin: top;
    }
    51% {
      transform-origin: bottom;

    }
    100% {
      transform: scaleY(0);
      transform-origin: bottom;
    }
  }
  @keyframes dt-marquee {
    to {
      transform: translateX(-50%);
    }
  }
  @keyframes dt-spin {
    to {
      transform: rotate(360deg);
    }
  }
  @keyframes dt-shake {
    0%,
    100% {
      transform: translateX(0);
    }
    20% {
      transform: translateX(-6px);
    }
    40% {
      transform: translateX(6px);
    }
    60% {
      transform: translateX(-4px);
    }
    80% {
      transform: translateX(3px);
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .dt-marquee-lane {
    transform: none;
  }
  .dt-marquee-track[aria-hidden] {
    display: none;
  }
  .dt-marquee {
    overflow-x: auto;
  }
  .dt-btn,
  .dt-btn::before,
  .dt-btn-label,
  .dt-pillar-card,
  .dt-access-form-wrap form,
  .dt-success,
  .dt-header {
    transition-duration: 120ms;
  }
}

@media (prefers-reduced-motion: no-preference) and (max-width: 860px) {
  .dt-hero-inner {
    transform: none;
  }
}

